window.listenToClawffee(["playAudio"], (_, value) => {
    if (!value || !value.url) {
        return;
    }

    const audio = document.createElement("audio");
    audio.src = value.url;
    audio.volume = typeof value.vol === "number" ? value.vol / 100 : 1;
    audio.playbackRate = typeof value.spd === "number" ? value.spd : 1;
    audio.autoplay = true;
    audio.addEventListener("ended", () => {
        if (audio.parentNode) {
            audio.parentNode.removeChild(audio);
        }
    });
    audio.addEventListener("error", (err) => {
        console.error(err);
        if (audio.parentNode) {
            audio.parentNode.removeChild(audio);
        }
    });
    document.body.appendChild(audio);
});

const emptyAudio = "data:audio/mp3;base64,"

const audio = document.createElement("audio");
audio.src = emptyAudio;
audio.loop = true;
document.body.appendChild(audio);
audio.addEventListener('error', (err) => {
    console.log(err);
})
window.addEventListener('click', () => {
    audio.play();
});